#include <optional>
#include <list>
#include <unordered_map>
#include <mutex>

template <typename K, typename V>
class LRUCache {
public:
    explicit LRUCache(std::size_t capacity)
        : capacity_(capacity) {}

    std::optional<V> get(const K& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_map_.find(key);
        if (it == cache_map_.end()) {
            return std::nullopt;
        }
        // Move the key to the front (most recently used)
        lru_list_.splice(lru_list_.begin(), lru_list_, it->second);
        return it->second->second;
    }

    void put(const K& key, const V& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_map_.find(key);
        if (it != cache_map_.end()) {
            // Update existing key: move to front and update value
            it->second->second = value;
            lru_list_.splice(lru_list_.begin(), lru_list_, it->second);
            return;
        }
        // Evict LRU if full
        if (lru_list_.size() == capacity_) {
            auto lru = lru_list_.rbegin();
            cache_map_.erase(lru->first);
            lru_list_.erase(lru);
        }
        // Add new entry at the front
        lru_list_.emplace_front(key, value);
        cache_map_[key] = lru_list_.begin();
    }

    std::size_t size() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return lru_list_.size();
    }

private:
    std::size_t capacity_;
    std::list<std::pair<K, V>> lru_list_;
    std::unordered_map<K, std::list<std::pair<K, V>>::iterator> cache_map_;
    mutable std::mutex mutex_;
};
