def word_freq(text, stop=[]):
    """Return (word, count) pairs: case-insensitive, punctuation ignored, words in stop excluded,
    most common first, ties in alphabetical order."""
    counts = {}
    for w in text.split():
        w = w.lower()
        w = ''.join(c for c in w if c.isalnum() or c == ' ')
        if not w:
            continue
        if w in stop:
            continue
