def topo_sort(graph):
    # Collect all nodes
    nodes = set(graph.keys())
    for prereqs in graph.values():
        for p in prereqs:
            nodes.add(p)

    # Build reverse dependency map: for each node, which nodes depend on it
    depends_on = {node: [] for node in nodes}
    for node, prereqs in graph.items():
        for p in prereqs:
            depends_on[p].append(node)

    # Compute in-degree (number of prerequisites for each node)
    in_degree = {}
    for node in nodes:
        in_degree[node] = len(graph.get(node, []))

    # Min-heap of nodes with no prerequisites
    import heapq
    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dependent in depends_on[node]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result
